import{_ as t,o as a,c as o,ai as d}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"Models","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/models.md","filePath":"en/guide/models.md"}'),l={name:"en/guide/models.md"};function r(i,e,s,n,c,m){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h1><p>The Models page is a browser for all models installed in your local Ollama instance, with detailed metadata and capability detection.</p><p><strong>Sidebar item:</strong> Models <strong>Route:</strong> <code>/settings?tab=models</code></p><h2 id="interface-overview" tabindex="-1">Interface Overview <a class="header-anchor" href="#interface-overview" aria-label="Permalink to &quot;Interface Overview&quot;">​</a></h2><p>The Models page (accessed via the Settings &gt; Models tab) displays a card or list for each installed model with key information at a glance.</p><h2 id="model-details" tabindex="-1">Model Details <a class="header-anchor" href="#model-details" aria-label="Permalink to &quot;Model Details&quot;">​</a></h2><p>Each model card shows:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Model identifier (e.g., <code>llama3.2:latest</code>)</td></tr><tr><td><strong>Parameter count</strong></td><td>Number of parameters (e.g., 3B, 7B, 70B)</td></tr><tr><td><strong>Quantization</strong></td><td>Compression level (e.g., Q4_0, Q8_0, F16)</td></tr><tr><td><strong>Family</strong></td><td>Model family (e.g., llama, mistral, gemma)</td></tr><tr><td><strong>Format</strong></td><td>Model format (e.g., gguf)</td></tr></tbody></table><h2 id="architecture-diagrams" tabindex="-1">Architecture Diagrams <a class="header-anchor" href="#architecture-diagrams" aria-label="Permalink to &quot;Architecture Diagrams&quot;">​</a></h2><p>Click on a model to see an architecture diagram showing the model&#39;s internal structure — layer count, attention heads, embedding dimensions, and more. This is parsed from Ollama&#39;s model metadata.</p><h2 id="capability-detection" tabindex="-1">Capability Detection <a class="header-anchor" href="#capability-detection" aria-label="Permalink to &quot;Capability Detection&quot;">​</a></h2><p>LLMxRay automatically detects what each model can do. Capabilities are read <strong>live from Ollama&#39;s <code>/api/show</code></strong>, so newly released models work without any update on LLMxRay&#39;s side. When a model doesn&#39;t self-report, LLMxRay falls back to name patterns.</p><table tabindex="0"><thead><tr><th>Capability</th><th>How it&#39;s detected</th><th>UI effect</th></tr></thead><tbody><tr><td><strong>Thinking</strong></td><td>Ollama <code>capabilities</code>, else name patterns (<code>deepseek-r1</code>, <code>qwq</code>, <code>gpt-oss</code>, <code>magistral</code>, <code>nemotron</code>, …)</td><td>Enables reasoning tab in Chat Diagnostics</td></tr><tr><td><strong>Vision</strong></td><td>Ollama <code>capabilities</code>, else name patterns (<code>llava</code>, <code>*-vl</code>, <code>moondream</code>, Llama-vision, …)</td><td>Enables image attachment in chat</td></tr><tr><td><strong>Embedding</strong></td><td>Ollama <code>capabilities</code> or model family</td><td>Appears in Embeddings and Knowledge Base model selectors</td></tr><tr><td><strong>Tool use</strong></td><td>Ollama <code>capabilities</code></td><td>Enables tool calling in chat</td></tr></tbody></table><p>Because capabilities come straight from Ollama, LLMxRay tracks new model families automatically; the name-pattern fallbacks — refreshed for families such as <strong>gpt-oss</strong>, <strong>Magistral</strong>, <strong>Nemotron</strong> (reasoning) and <strong>Moondream</strong> / Llama-vision — only apply when a model doesn&#39;t report its own capabilities.</p><p>Models that support only embeddings are automatically filtered out of chat model selectors.</p><h2 id="model-catalog" tabindex="-1">Model Catalog <a class="header-anchor" href="#model-catalog" aria-label="Permalink to &quot;Model Catalog&quot;">​</a></h2><p>The catalog provides a curated view of available models with comparison tables, helping you choose the right model for your use case.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Quantization trade-off</strong> — Lower quantization (Q4) uses less RAM but slightly reduces quality. Q8 and F16 are higher quality but need more memory.</li><li><strong>Pull more models</strong> from the terminal: <code>ollama pull &lt;model-name&gt;</code></li><li>The capability detection adapts the entire UI — you don&#39;t need to configure anything manually.</li></ul>',19)])])}const p=t(l,[["render",r]]);export{g as __pageData,p as default};
